/**
 * Creating or deleting a repository in place (the Workbench router posts for page data) answers a failure with the
 * page's own error model and an error status, instead of a container error page the router cannot read.
 */
class CreateDeletePageDataErrorTest {

	private static final ObjectMapper JSON_MAPPER = new ObjectMapper();

	@Test
	void aRejectedCreateAnswersTheCreatePageWithItsErrorMessage() throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		doThrow(new RepositoryConfigException("A repository with ID fed already exists"))
				.when(manager)
				.addRepositoryConfig(any(RepositoryConfig.class));
		CreateServlet servlet = new CreateServlet();
		MockHttpServletRequest request = pageDataPost("/create");
		request.addParameter("type", "federate");
		request.addParameter("Local repository ID", "fed");
		request.addParameter("Repository title", "Federation");
		request.addParameter("memberID", "alpha");

		MockHttpServletResponse response = run(servlet, "create", manager, request);

		assertThat(response.getStatus()).isEqualTo(400);
		assertThat(response.getContentType()).startsWith(WorkbenchPageProtocol.ACCEPT);
		List<JsonNode> records = records(response);
		assertThat(view(records)).isEqualTo("create");
		assertThat(errorMessage(records)).contains("A repository with ID fed already exists");
	}

	@Test
	void aFailedDeleteAnswersTheDeletePageWithItsErrorMessage() throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		doThrow(new RepositoryException("The repository is in use")).when(manager).removeRepository("memory");
		DeleteServlet servlet = new DeleteServlet();
		MockHttpServletRequest request = pageDataPost("/delete");
		request.addParameter("id", "memory");

		MockHttpServletResponse response = run(servlet, "delete", manager, request);

		assertThat(response.getStatus()).isEqualTo(500);
		assertThat(response.getContentType()).startsWith(WorkbenchPageProtocol.ACCEPT);
		List<JsonNode> records = records(response);
		assertThat(view(records)).isEqualTo("delete");
		assertThat(errorMessage(records)).contains("The repository is in use");
	}

	/** C25: the safety check of a delete answers JSON, and says so, so browsers do not parse it as XML. */
	@Test
	void theDeleteSafetyCheckAnswersJson() throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		when(manager.isSafeToRemove("memory")).thenReturn(true);
		MockHttpServletRequest request = new MockHttpServletRequest("GET", "/delete");
		request.addParameter("checkSafe", "memory");

		MockHttpServletResponse response = run(new DeleteServlet(), "delete", manager, request);

		assertThat(response.getContentType()).startsWith("application/json");
		assertThat(JSON_MAPPER.readTree(response.getContentAsString()).path("safe").asBoolean()).isTrue();
	}

	/**
	 * C14: an ID becomes a segment of the Workbench's and the server's URLs (and, on a local server, a directory name),
	 * so the Workbench only creates repositories whose ID needs no escaping there.
	 */
	@ParameterizedTest
	@ValueSource(strings = { "bad id", "a/b", "q?x", "50%", "bøk", "..", "." })
	void aRepositoryIdThatIsNotUrlSafeIsRejectedWithAClearMessage(String id) throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		MockHttpServletRequest request = pageDataPost("/create");
		request.addParameter("type", "memory");
		request.addParameter("Repository ID", id);
		request.addParameter("Repository title", "Memory store");

		MockHttpServletResponse response = run(new CreateServlet(), "create", manager, request);

		assertThat(response.getStatus()).isEqualTo(400);
		List<JsonNode> records = records(response);
		assertThat(view(records)).isEqualTo("create");
		assertThat(errorMessage(records)).isEqualTo("Repository ID '" + id
				+ "' is not valid: use only the letters a-z and A-Z, digits, '-', '_', '.' and '@', and not only dots.");
		verify(manager, never()).addRepositoryConfig(any(RepositoryConfig.class));
	}

	@Test
	void aFederationIdThatIsNotUrlSafeIsRejected() throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		MockHttpServletRequest request = pageDataPost("/create");
		request.addParameter("type", "federate");
		request.addParameter("Local repository ID", "my federation");
		request.addParameter("Repository title", "Federation");
		request.addParameter("memberID", "alpha");

		MockHttpServletResponse response = run(new CreateServlet(), "create", manager, request);

		assertThat(response.getStatus()).isEqualTo(400);
		assertThat(errorMessage(records(response))).startsWith("Repository ID 'my federation' is not valid");
		verify(manager, never()).addRepositoryConfig(any(RepositoryConfig.class));
	}

	@Test
	void anEmptyRepositoryIdIsRejected() throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		MockHttpServletRequest request = pageDataPost("/create");
		request.addParameter("type", "memory");
		request.addParameter("Repository ID", "");
		request.addParameter("Repository title", "Memory store");

		MockHttpServletResponse response = run(new CreateServlet(), "create", manager, request);

		assertThat(response.getStatus()).isEqualTo(400);
		assertThat(errorMessage(records(response))).isEqualTo("Enter a repository ID.");
		verify(manager, never()).addRepositoryConfig(any(RepositoryConfig.class));
	}

	@ParameterizedTest
	@ValueSource(strings = { "memory", "My_Repo-2.0", ".hidden", "a..b", "SYSTEM@localhost" })
	void aUrlSafeRepositoryIdIsCreated(String id) throws Exception {
		RepositoryManager manager = mock(RepositoryManager.class);
		MockHttpServletRequest request = pageDataPost("/create");
		request.addParameter("type", "memory");
		request.addParameter("Repository ID", id);
		request.addParameter("Repository title", "Memory store");

		MockHttpServletResponse response = run(new CreateServlet(), "create", manager, request);

		assertThat(response.getRedirectedUrl()).isEqualTo("../" + id + "/summary");
		verify(manager).addRepositoryConfig(any(RepositoryConfig.class));
	}

	private static MockHttpServletRequest pageDataPost(String path) {
		MockHttpServletRequest request = new MockHttpServletRequest("POST", path);
		request.addHeader("Accept", WorkbenchPageProtocol.ACCEPT);
		return request;
	}

	private static MockHttpServletResponse run(TransformationServlet servlet, String name, RepositoryManager manager,
			MockHttpServletRequest request) throws Exception {
		servlet.setRepositoryManager(manager);
		servlet.init(TestServletConfig.withParams(name, "cookie-max-age", "300"));
		try {
			MockHttpServletResponse response = new MockHttpServletResponse();
			servlet.service(request, response);
			return response;
		} finally {
			servlet.destroy();
		}
	}

	private static List<JsonNode> records(MockHttpServletResponse response) throws Exception {
		return response.getContentAsString()
				.lines()
				.filter(line -> !line.isBlank())
				.map(JSON_MAPPER::readTree)
				.toList();
	}

	private static String view(List<JsonNode> records) {
		return records.stream()
				.filter(record -> "view".equals(record.path("type").asText()))
				.map(record -> record.path("id").asText())
				.findFirst()
				.orElse(null);
	}

	/** The error-message column of the error row. */
	private static String errorMessage(List<JsonNode> records) {
		List<String> vars = records.stream()
				.filter(record -> "vars".equals(record.path("type").asText()))
				.flatMap(record -> {
					List<String> names = new java.util.ArrayList<>();
					record.path("values").forEach(value -> names.add(value.asText()));
					return names.stream();
				})
				.toList();
		int column = vars.indexOf("error-message");
		assertThat(column).as("error-message column in %s", vars).isGreaterThanOrEqualTo(0);
		return records.stream()
				.filter(record -> "rows".equals(record.path("type").asText()))
				.map(record -> record.path("values").get(0).get(column).path("value").asText())
				.findFirst()
				.orElse(null);
	}
}
